import {expandedInferenceReviewHolds,expandedScopeReviews} from './expanded-top-review-data.js';
import {expandedOccupationById,expandedOccupations} from './expanded-occupation-data.js';
import {expandedQuestionBank} from './expanded-question-bank.js';
import {scoreOnetInterest,profileCorrelation,interestFit} from './onet-assessment.js';
export const expandedResponses=['yes','no','unsure','unfamiliar'];
const questionById=new Map(Object.values(expandedQuestionBank).flatMap(b=>b.questions||[]).map(q=>[q.id,q]));
export function cleanExpandedInterests(raw){const out={};for(const[id,a]of Object.entries(raw||{})){const q=questionById.get(id);if(!q||!expandedResponses.includes(a?.response))continue;out[id]={response:a.response,confidence:['high','medium','low'].includes(a.confidence)?a.confidence:(a.source==='profile-inferred'?'low':'high'),source:a.source==='profile-inferred'?'profile-inferred':'student',evidence:String(a.evidence||'').slice(0,1800),...(a.source==='profile-inferred'&&a.reviewHold?{reviewHold:String(a.reviewHold).slice(0,1800)}:{})};}return out;}
export function expandedInterestStatus(s,id){const b=expandedQuestionBank[id],questions=(b?.questions||[]).map(q=>({...q,answer:s.profileJourney?.expandedInterests?.[q.id]||null})),supports=a=>a?.response==='yes'&&!a.reviewHold&&(a.source!=='profile-inferred'||(['high','medium'].includes(a.confidence)&&a.evidence?.trim())),count=questions.filter(q=>supports(q.answer)).length,declined=questions.some(q=>q.answer?.response==='no'),confirmed=b?.topEligible===true&&questions.length===3&&new Set(questions.map(q=>q.domain)).size===3&&count===3&&!declined,next=questions.find(q=>!supports(q.answer))||questions[0];return {version:'0.47.0',scopeReview:s._expandedScopeReviews?.[id]||null,confirmed,declined,inferred:questions.some(q=>q.answer?.source==='profile-inferred'),supportCount:count,reviewHolds:questions.filter(q=>q.answer?.reviewHold),code:confirmed?'confirmed':declined?'not-interested':'needs-confirmation',headline:confirmed?'Three distinct work interests supported':'More interest evidence needed',detail:confirmed?'Subject interest, method and distinctive responsibility have supporting answers. This is an interest match, not proof of aptitude, admission or professional qualification.':'Unknown or unfamiliar work stays open. A related hobby or general strength alone does not establish this profession.',questions,nextQuestionId:next?.id};}
export function updateExpandedInterest(s,id,questionId,response){const b=expandedQuestionBank[id];if(!b?.topEligible||!b.questions.some(q=>q.id===questionId)||!expandedResponses.includes(response))return false;s.profileJourney.expandedInterests??={};s.profileJourney.expandedInterests[questionId]={response,confidence:'high',source:'student',evidence:'Own reflection after reading the work comparison.'};return true;}
export function expandedInterestState(state,record){const s=structuredClone(state);if(!record)return s;if(record.version!==3||!Array.isArray(record.professions))throw Error('Invalid expanded-interest replay');s.profileJourney.expandedInterests??={};s._expandedScopeReviews=Object.fromEntries(expandedScopeReviews.filter(r=>r.modelId===record.id).map(r=>[r.careerId,r]));const seen=new Set();for(const p of record.professions){const b=expandedQuestionBank[p.id];if(seen.has(p.id)||!b?.topEligible||p.answers.length!==3)throw Error('Invalid expanded profession '+p.id);seen.add(p.id);for(const q of b.questions){const a=p.answers.find(a=>a.questionId===q.id);if(!a||!expandedResponses.includes(a.response)||!['high','medium','low'].includes(a.confidence)||!a.evidence?.trim())throw Error('Invalid expanded answer '+q.id);const hold=expandedInferenceReviewHolds.find(h=>h.modelId===record.id&&h.careerId===p.id&&h.questionId===q.id);s.profileJourney.expandedInterests[q.id]={...a,source:'profile-inferred',...(hold?{reviewHold:hold.reason}:{})};}}return s;}
export function expandedMatchCandidates(s){if(s._historicalMatchRules||s._disableExpandedMatches||!Object.keys(s.profileJourney?.expandedInterests||{}).length)return [];const p=scoreOnetInterest(s);if(!p.complete||p.flat||p.nearFlat)return [];const rows=[];for(const o of expandedOccupations){const c=expandedInterestStatus(s,o.id);if(!c.supportCount||c.declined||!o.vector)continue;const r=profileCorrelation(p.raw,o.vector),fit=interestFit(r);if(fit.tier<2)continue;const evidence=c.questions.filter(q=>q.answer?.response==='yes'&&!q.answer.reviewHold&&(q.answer.source!=='profile-inferred'||['high','medium'].includes(q.answer.confidence))).map(q=>({questionId:q.id,question:q.prompt,text:q.prompt,domain:q.domain,source:q.answer.source,confidence:q.answer.confidence,profileEvidence:q.answer.evidence}));rows.push({id:o.id,o,expandedDegree:true,supported:true,basis:'profile-and-tasks',score:evidence.length,taskTotal:3,answeredTasks:c.questions.filter(q=>q.answer).length,specificSupport:0,routeSupport:false,interestMatch:{...fit,r,eligible:true},domains:evidence.map(e=>e.domain),evidence,reasons:evidence.map(e=>e.profileEvidence||e.text),confirmation:c});}return rows;}
export function expandedUnknownOpportunity(o){return {id:o.id,o,interest:null,requiresExperience:o.requiresExperience,firstPay:null,qualifiedPay:null,meetsAtStart:null,meetsQualified:null,start:null,routes:[{key:o.educationGroup,label:o.educationGroup==='graduate'?'Graduate / professional degree':'College · bachelor’s degree'}],connection:'Three distinct interests support this career. Pay and preparation costs need separate verification.'};}
